#include <zephyr/ztest.h>
#include <zephyr/storage/flash_map.h>
#include <zephyr/drivers/flash.h>

#define TEST_FLASH_AREA		storage_partition
#define TEST_FLASH_AREA_ID	FIXED_PARTITION_ID(TEST_FLASH_AREA)

static const struct flash_area *fa;

static void *flash_map_api_setup(void)
{
	int rc;

	rc = flash_area_open(TEST_FLASH_AREA_ID, &fa);
	zassert_equal(rc, 0, "flash_area_open() failed");

	/* Erase the whole area to have a clean state */
	rc = flash_area_erase(fa, 0, fa->fa_size);
	zassert_equal(rc, 0, "flash_area_erase() failed");

	return NULL;
}

static void flash_map_api_teardown(void *data)
{
	ARG_UNUSED(data);

	if (fa != NULL) {
		flash_area_close(fa);
		fa = NULL;
	}
}

ZTEST(flash_map_api, test_get_mock)
{
	ztest_test_skip();
}

ZTEST(flash_map_api, test_double_write)
{
	ztest_test_skip();
}

ZTEST(flash_map_api, test_erase_capability)
{
	const struct flash_driver_api *api = fa->fa_dev->api;
	struct flash_pages_info page_info;
	off_t page_offset;

	zassert_true(api->page_layout != NULL, "page_layout API is not available");

	/* First check with valid offset */
	page_offset = fa->fa_off;
	zassert_ok(flash_get_page_info_by_offs(fa->fa_dev, page_offset, &page_info));

	/* Last byte of the area */
	page_offset = fa->fa_off + fa->fa_size - 1;
	zassert_ok(flash_get_page_info_by_offs(fa->fa_dev, page_offset, &page_info));
}

ZTEST(flash_map_api, test_flash_fill)
{
	int rc;
	uint8_t buf[16];
	const uint8_t fill_val = 0x55;
	const uint8_t erase_val = flash_area_get_parameters(fa)->erase_value;

	rc = flash_area_write(fa, 0, &fill_val, 1);
	zassert_equal(rc, 0, "flash_area_write() failed");

	rc = flash_area_read(fa, 0, buf, sizeof(buf));
	zassert_equal(rc, 0, "flash_area_read() failed");

	for (int i = 0; i < sizeof(buf); i++) {
		if (i == 0) {
			zassert_equal(buf[i], fill_val, "buf[%d] is wrong", i);
		} else {
			zassert_equal(buf[i], erase_val, "buf[%d] is wrong", i);
		}
	}
}

ZTEST(flash_map_api, test_flash_flatten)
{
	int rc;
	uint8_t buf[16];
	const uint8_t fill_val = 0x55;
	const uint8_t erase_val = flash_area_get_parameters(fa)->erase_value;

	/* 1. Flatten an already erased area */
	rc = flash_area_flatten(fa, 0, sizeof(buf));
	zassert_equal(rc, 0, "flash_area_flatten() failed");

	rc = flash_area_read(fa, 0, buf, sizeof(buf));
	zassert_equal(rc, 0, "flash_area_read() failed");

	for (int i = 0; i < sizeof(buf); i++) {
		zassert_equal(buf[i], erase_val, "buf[%d] is wrong", i);
	}

	/* 2. Write some data and then flatten */
	rc = flash_area_write(fa, 0, &fill_val, 1);
	zassert_equal(rc, 0, "flash_area_write() failed");

	rc = flash_area_flatten(fa, 0, sizeof(buf));
	zassert_equal(rc, 0, "flash_area_flatten() failed");

	rc = flash_area_read(fa, 0, buf, sizeof(buf));
	zassert_equal(rc, 0, "flash_area_read() failed");

	for (int i = 0; i < sizeof(buf); i++) {
		zassert_equal(buf[i], erase_val, "buf[%d] is wrong", i);
	}
}

ZTEST(flash_map_api, test_get_erase_value)
{
	const struct flash_parameters *fp = flash_area_get_parameters(fa);
	const struct flash_parameters *dev_fp = flash_get_parameters(fa->fa_dev);

	zassert_equal(fp->erase_value, dev_fp->erase_value, "erase_value is wrong");
}

ZTEST(flash_map_api, test_out_of_bounds)
{
	int rc;
	uint8_t buf[16];

	/*
	 * The behavior of out-of-bounds access depends on the underlying driver
	 * and hardware. On POSIX-based targets using the flash simulator, this
	 * will cause a segmentation fault, which must be expected by the test
	 * framework.
	 */
	ztest_expect_fault();
	rc = flash_area_read(fa, fa->fa_size, buf, sizeof(buf));

	/* This part of the test will not be reached if a fault occurs as expected */
	zassert_not_equal(rc, 0, "flash_area_read() should fail for out of bounds access");
}

ZTEST_SUITE(flash_map_api, NULL, flash_map_api_setup, NULL, NULL, flash_map_api_teardown);
